TLM.f("Sancti/02-12",{"officium":"Ss. Septem Fundat. Ord. Servorum B. M. V.","rule":["vide C5;;","Gloria"],"fallback":"Commune/C5","sections":{"Introitus":[{"k":"ref","la":"Sap 10:20-21"},{"k":"text","la":"Justi decantavérunt, Dómine, nomen sanctum tuum, et victrícem manum tuam laudavérunt páriter: quóniam sapiéntia apéruit os mutum et linguas infántium fecit disértas."},{"k":"ref","la":"Ps 8:2"},{"k":"text","la":"Dómine, Dóminus noster, quam admirábile est nomen tuum in univérsa terra!"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Justi decantavérunt, Dómine, nomen sanctum tuum, et victrícem manum tuam laudavérunt páriter: quóniam sapiéntia apéruit os mutum et linguas infántium fecit disértas."}],"Oratio":[{"k":"text","la":"Dómine Jesu Christe, qui, ad recoléndam memóriam dolórum sanctíssimæ Genetrícis tuæ, per septem beátos Patres nova Servorum ejus família Ecclésiam tuam fœcundásti: concéde propítius; ita nos eórum consociári flétibus, ut perfruámur et gáudiis:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 44:1-15"},{"k":"text","la":"Laudémus viros gloriósos et paréntes nostros in generatióne sua. Multam glóriam fecit Dóminus magnificéntia sua a sǽculo. Dominántes in potestátibus suis, hómines magni virtúte et prudéntia sua præditi, nuntiántes in prophétis dignitátem prophetárum, et imperántes in præsénti pópulo, et virtúte prudéntiæ pópulis sanctíssima verba. In perítia sua requiréntes modos músicos, et narrántes cármina scripturárum. Hómines dívites in virtúte, pulchritúdinis stúdium habéntes: pacificántes in dómibus suis. Omnes isti in generatiónibus gentis suæ glóriam adépti sunt, et in diébus suis habéntur in láudibus. Qui de illis nati sunt, reliquérunt nomen narrándi laudes eórum. Et sunt, quorum non est memória: periérunt, quasi qui non fúerint: et nati sunt, quasi non nati, et fílii ipsórum cum ipsis. Sed illi viri misericórdiæ sunt, quorum pietátes non defuérunt: cum sémine eórum pérmanent bona, heréditas sancta nepótes eórum, et in testaméntis stetit semen eórum: et fílii eórum propter illos usque in ætérnum manent: semen eórum et glória eórum non derelinquétur. Córpora ipsórum in pace sepúlta sunt, et nomen eórum vivit in generatiónem et generatiónem. Sapiéntiam ipsórum narrent pópuli, et laudem eórum núntiet Ecclésia."}],"Graduale":[{"k":"ref","la":"Is 65:23"},{"k":"text","la":"Elécti mei non laborábunt frustra, neque germinábunt in conturbatióne: quia semen benedictórum Dómini est, et nepótes eórum cum eis."},{"k":"ref","la":"Eccli 44:14"},{"k":"text","la":"Córpora ipsorum in pace sepúlta sunt, et nomen eórum vivit in generatiónem et generatiónem. Allelúja, allelúja."},{"k":"ref","la":"Eccli 44:15"},{"k":"text","la":"Sapiéntiam ipsorum narrent pópuli, et laudem eórum núntiet Ecclésia. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Eccli 44:15"},{"k":"text","la":"Sapiéntiam ipsórum narrent pópuli, et laudem eórum núntiet Ecclésia."},{"k":"ref","la":"Ps 36:28"},{"k":"text","la":"Non derelínquet Dóminus sanctos suos: in ætérnum conservabúntur. Allelúja."}],"Tractus":[{"k":"ref","la":"Is 65:23"},{"k":"text","la":"Elécti mei non laborábunt frustra, neque germinábunt in conturbatióne: quia semen benedictórum Dómini est, et nepótes eórum cum eis."},{"k":"ref","la":"Eccli 44:14"},{"k":"text","la":"Córpora ipsorum in pace sepúlta sunt, et nomen eórum vivit in generatiónem et generatiónem."},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in exsultatióne metent."},{"k":"text","la":"Eúntes ibant et fiébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 19:27-29"},{"k":"text","la":"In illo témpore: Dixit Petrus ad Jesum: Ecce, nos relíquimus ómnia, et secúti sumus te: quid ergo erit nobis? Jesus autem dixit illis: Amen, dico vobis, quod vos, qui secúti estis me, in regeneratióne, cum séderit Fílius hóminis in sede majestátis suæ, sedébitis et vos super sedes duódecim, judicántes duódecim tribus Israël. Et omnis, qui relíquerit domum, vel fratres, aut soróres, aut patrem, aut matrem, aut uxórem, aut fílios, aut agros, propter nomen meum, céntuplum accípiet, et vitam ætérnam possidébit."}],"Offertorium":[{"k":"ref","la":"Is 56:7"},{"k":"text","la":"Addúcam eos in montem sanctum meum, et lætificábo eos in domo oratiónis meæ: holocáusta eórum et víctimæ eórum placébunt mihi super altáre meum."}],"Secreta":[{"k":"text","la":"Accipe, quǽsumus, Dómine, hóstias quas tibi offérimus: et præsta; ut, intercedéntibus Sanctis tuis, libera tibi mente serviámus, et perdoléntis Vírginis Genetrícis Fílii tui amóre inflammémur."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Joann 15:16"},{"k":"text","la":"Ego vos elégi de mundo, ut eátis et fructum afferátis: et fructus vester máneat."}],"Postcommunio":[{"k":"text","la":"Cœléstibus refécti mystériis te, Dómine, deprecámur: ut, quorum festa percólimus imitántes exémpla; juxta Crucem Jesu cum María Matre ejus fidéliter astémus, et ejúsdem redemptiónis fructum percípere mereámur."},{"k":"macro","name":"Per eundem"}]},"hr":{"ca2030aa2736b8a4":{"t":"Mudr 10, 20-21, Ps 8, 2\n(Mudr 10, 20-21) Pravednici su opjevali tvoje sveto ime. Gospodine, i pobjednicu ruku tvoju skupno su hvalili, jer je mudrost otvorila nijema usta i učinila da govore i dječja usta. (Ps 8, 2) Gospodine, Gospodine naš, kako li je divno ime tov je po svoj zemlji!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mudr 10, 20-21) Pravednici su opjevali tvoje sveto ime. Gospodine, i pobjednicu ruku tvoju skupno su hvalili, jer je mudrost otvorila nijema usta i učinila da govore i dječja usta."},"a1a563febacdefa4":{"t":"<i>Pomolimo se</i>.\nGospodine Isuse Kriste, koji si posredstvom sedam svetih otaca za štovanje uspomene na boli presvete Majke svoje obogatio Crkvu novom obitelju njezinih Slugu, daj milostivo da se tako združimo s njihovim plačem te uživamo i u njihovim radostima:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"9ed88ae9d6e4eabf":{"t":"Sir 44, 1-15\nČitanje knjige Mudrosti. Hvalimo slavne muževe, naše pretke, jer pripadamo njihovu rodu. Gospodin im je svojom moći od vijeka pribavio Veliku slavu. Vladali su u svojim kraljevstvima, bili su velikani obdareni razboritošću, nastupali su proročkim dostojanstvom, vodili su narod svojega vremena, posebnom su mudrošću predali narodima nauku Svetosti. Bili su vješti izumitelji skladnih popijevaka i ispjevali nadahnute pjesme. Bogati krepostima, uživala su u ljepoti i čuvali mir u: svojim kućama. Prestigli su slavom svoje suvremenike i bit će čašćeni od budućih naraštaja, jer su svojim potomcima ostavili časno ime, da mogu propovijedati njihovu slavu. A ima ljudi kojima nema spomena. Nestalo ih je kao da se nisu ni rodili, ni oni, ni njihova djeca. Oni prvi su ljudi ljubitelji braće i djela njihova milosrđa neće nestati. Dobra im djela ostaju potomstvu. I radi njih će vječno ostati njihova djeca. I neće nestati ni njihova roda, ni njihove slave! Tjelesa su im sahranjena u miru, a njihovo će ime živjeti od koljena do koljena. Neka narodi govore o njihovoj mudrosti, a crkva neka razglašuje njihovu hvalu!"},"3d776c28b5a11073":{"t":"Iz 65, 23, Sir 44, 14\n(Iz 65, 23) Odabranici moji neće se truditi uzalud, niti će njihovo nastojanje biti bez ploda, jer su oni i njihovi potomci rod blagoslovljen od Gospodina. (Sir 44, 14) Tjelesa su njihova pokopana u miru, a ime njihovo živi od pokoljenja do pokoljenja.\n\nPs 125, 5-6\nKoji siju u suzama u radosti će žeti. Tužno koračaju i plaču noseći sjeme za sjetvu. Ali će doći, doći će s klicanjem noseći snopove svoje.","v":"gaudio → exsultatione"},"9c583f5745d0c082":{"t":"Mt 19, 27-29\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Petar Isusu: Evo, mi smo ostavili sve i pošli za tobom. Što će, dakle, biti s nama? Isus im odgovori: Zaista vam kažem kad u vrijeme preporoda bude Sin čovječji sjedio na prijestolju svoga veličanstva, i vi koji ste pošli za mnom sjedit ćete na dvanaest prijestolja i suditi dvanaest Izraelskih plemena. A svaki koji radi mene ostavi kuću, ili braću, ili sestre, ili oca, ili majku, ili ženu, ili djecu ili polja, primit će stoput više i imat će vječni život."},"8bf5469563e22c31":{"t":"Iz 56, 7\nDovest ću ih na goru svetu svoju i razveselit ću ih u svome domu molitve. Paljenice njihove i žrtve njihove bit će mi ugodne na žrtveniku mome."},"0930dcfa06f0e41e":{"t":"Primi, Gospodine, darove koje ti prikazujemo i daj da ti po zagovoru tvojih svetih služimo slobodnim duhom i da se raspalimo ljubavlju prema prežalosnoj Djevici Majci Sina tvoga.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"87407971675a9e99":{"t":"Iv 15, 16\nJa sam vas izabrao ođ svijeta da idete i plod donesete i plod vaš da ostane."},"e80e4976a24676d8":{"t":"<i>Pomolimo se</i>.\nNebeskim tajnama okrijepljeni molimo te, Gospodine, daj da nasljedujući primjere svetih kojih blagdan slavimo vjerno stojimo uz križ Isusov s Marijom Majkom njegovom i zavrijedimo primiti plod njegova otkupljenja.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"7036099b6c6095ab":null}});
